<?php $isEdit = $section === 'vehicles-edit'; $formTitle = $isEdit ? 'Edit Vehicle' : 'Add Vehicle'; $formAction = 'index.php?page=admin&amp;section=' . $section . ($isEdit ? '&amp;id=' . (int) $id : ''); ?>
<div class="customer-heading vehicle-heading vehicle-add-heading"><div><div class="breadcrumb-line">Dashboard <span>›</span> Vehicles <span>›</span> <b><?= $formTitle ?></b></div><h1><?= $formTitle ?></h1><p><?= $isEdit ? 'Update the registered vehicle information.' : 'Add another vehicle to an existing customer without creating a duplicate customer.' ?></p></div><a class="btn btn-light" href="index.php?page=admin&amp;section=vehicles">← Back to Vehicles</a></div>
<div class="admin-panel vehicle-entry-panel vehicle-add-card"><?php if ($errors): ?><div class="alert alert-danger"><?php foreach ($errors as $error): ?><div><?= e($error) ?></div><?php endforeach; ?></div><?php endif; ?><div class="vehicle-add-intro"><strong>Vehicle Information</strong><span>Select the customer first. You can register any number of vehicles under the same customer.</span></div><form method="post" action="<?= e($formAction) ?>"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><div class="row g-3"><div class="col-md-6 col-xl-4"><label class="form-label">Customer <span>*</span></label><select class="form-select" name="customer_id" required><option value="">Select Customer</option><?php foreach ($customers as $customer): ?><option value="<?= (int) $customer['id'] ?>" <?= (int) $input['customer_id'] === (int) $customer['id'] ? 'selected' : '' ?>><?= e($customer['name'] . ' (' . $customer['contact_number'] . ')') ?></option><?php endforeach; ?></select><small class="vehicle-form-link"><?= $isEdit ? 'Choose the customer for this vehicle.' : 'The vehicle will be linked to this customer.' ?></small></div><div class="col-md-6 col-xl-4"><label class="form-label">Vehicle No <span>*</span></label><input class="form-control" name="vehicle_number" value="<?= e($input['vehicle_number']) ?>" placeholder="Enter vehicle number" required maxlength="40"></div><div class="col-md-6 col-xl-4"><label class="form-label">Vehicle Type <span>*</span></label><select class="form-select" name="vehicle_type" required><option value="">Select vehicle type</option><?php foreach (['Motorcycle','Car','Van','SUV','Three Wheeler','Truck','Other'] as $type): ?><option value="<?= e($type) ?>" <?= $input['vehicle_type'] === $type ? 'selected' : '' ?>><?= e($type) ?></option><?php endforeach; ?></select></div><div class="col-md-6 col-xl-4"><label class="form-label">Make / Brand</label><input class="form-control" name="make" value="<?= e($input['make']) ?>" placeholder="Enter make or brand" maxlength="100"></div><div class="col-md-6 col-xl-4"><label class="form-label">Model <span>*</span></label><input class="form-control" name="model" value="<?= e($input['model']) ?>" placeholder="Enter model" required maxlength="100"></div><div class="col-md-6 col-xl-4"><label class="form-label">Year</label><select class="form-select" name="year"><option value="">Select year</option><?php for ($year = (int) date('Y') + 1; $year >= 1950; $year--): ?><option value="<?= $year ?>" <?= (string) $input['year'] === (string) $year ? 'selected' : '' ?>><?= $year ?></option><?php endfor; ?></select></div><div class="col-md-6 col-xl-4"><label class="form-label">Colour</label><input class="form-control" name="colour" value="<?= e($input['colour']) ?>" placeholder="Enter colour" maxlength="60"></div><div class="col-md-6 col-xl-4"><label class="form-label">Engine Number</label><input class="form-control" name="engine_number" value="<?= e($input['engine_number']) ?>" placeholder="Enter engine number" maxlength="100"></div><div class="col-md-6 col-xl-4"><label class="form-label">Chassis Number</label><input class="form-control" name="chassis_number" value="<?= e($input['chassis_number']) ?>" placeholder="Enter chassis number" maxlength="100"></div><div class="col-md-6 col-xl-4"><label class="form-label">Fuel Type</label><select class="form-select" name="fuel_type"><option value="">Select fuel type</option><?php foreach (['Petrol','Diesel','Hybrid','Electric','Other'] as $fuel): ?><option value="<?= e($fuel) ?>" <?= $input['fuel_type'] === $fuel ? 'selected' : '' ?>><?= e($fuel) ?></option><?php endforeach; ?></select></div><div class="col-md-6 col-xl-4"><label class="form-label">Current Mileage (KM) <span>*</span></label><div class="input-group"><input class="form-control" type="number" min="0" step="0.01" name="current_mileage" value="<?= e($input['current_mileage']) ?>" placeholder="Enter current mileage" required><span class="input-group-text">km</span></div></div><div class="col-12"><label class="form-label">Notes (Optional)</label><textarea class="form-control" name="notes" rows="3" placeholder="Enter any additional notes..."><?= e($input['notes']) ?></textarea></div></div><div class="customer-form-actions"><a class="btn btn-light" href="index.php?page=admin&amp;section=vehicles">Cancel</a><?php if (!$isEdit): ?><button class="btn btn-danger" type="reset">Reset</button><?php endif; ?><button class="btn btn-danger" type="submit"><?= $isEdit ? 'Update Vehicle' : 'Save Vehicle' ?></button></div></form></div>
